#![forbid(unsafe_code)]

// Include the unchanged production module directly. This deliberately validates
// only its own bridge seam, not the entire fsym-python extension or shell APIs.
#[path = "/workspace/scratch/fdf3b50928f6/frankensympy/crates/fsym-python/src/numeric_budget.rs"]
mod numeric_budget;

#[cfg(test)]
mod tests {
    use super::numeric_budget::{
        EvaluationBudgetExceeded, EvaluationCancelled, PyEvaluationBudget,
        evaluation_error, register, with_evaluation_meter,
    };
    use fsym_budget::{Budget, BudgetLimits, Dimension, MeterError};
    use fsym_calculus::{CompiledExpr, CompiledOp, EvalError, ObjectiveEvaluationError};
    use pyo3::exceptions::{PyRuntimeError, PyValueError};
    use pyo3::prelude::*;
    use pyo3::types::PyDict;
    use std::ffi::CString;

    fn module(py: Python<'_>) -> Bound<'_, PyModule> {
        let module = PyModule::new(py, "fsym_python").unwrap();
        register(&module).unwrap();
        module
    }

    fn budget<'py>(module: &Bound<'py, PyModule>, steps: u64) -> Bound<'py, PyAny> {
        let kwargs = PyDict::new(module.py());
        kwargs.set_item("max_steps", steps).unwrap();
        module.getattr("EvaluationBudget").unwrap().call((), Some(&kwargs)).unwrap()
    }

    fn remaining(instance: &Bound<'_, PyAny>, name: &str) -> u64 {
        instance.getattr(name).unwrap().extract().unwrap()
    }

    #[test]
    fn actual_python_constructor_strict_limits_atomic_charges_and_sticky_cancellation() {
        Python::initialize();
        Python::attach(|py| {
            let module = module(py);
            let globals = module.dict();
            let source = CString::new(r#"
def raises(kind, action):
    try:
        action()
    except kind:
        return
    raise AssertionError('expected ' + kind.__name__)

b = EvaluationBudget()
assert b.remaining_steps == 10_000_000
assert b.remaining_memory_bytes == 256 * 1024 * 1024
assert b.remaining_allocations == 100_000
assert not b.cancelled
assert EvaluationBudget(max_steps=None).remaining_steps == b.remaining_steps
calls = []
class CustomInt(int):
    def __index__(self):
        calls.append('index')
        return 1
for option in ('max_steps', 'max_memory_bytes', 'max_allocations'):
    for value in (True, 1.0, '1', CustomInt(1)):
        raises(TypeError, lambda: EvaluationBudget(**{option: value}))
    for value in (-1, 2**64):
        raises(ValueError, lambda: EvaluationBudget(**{option: value}))
    assert EvaluationBudget(**{option: 0}) is not None
assert calls == []
limited = EvaluationBudget(max_steps=7, max_memory_bytes=0, max_allocations=2)
raises(EvaluationBudgetExceeded, lambda: limited._charge(3, memory_bytes=1, allocations=1))
assert (limited.remaining_steps, limited.remaining_memory_bytes, limited.remaining_allocations) == (7, 0, 2)
limited._charge(3, allocations=1)
assert (limited.remaining_steps, limited.remaining_allocations) == (4, 1)
limited.cancel()
limited.cancel()
assert limited.cancelled
raises(EvaluationCancelled, limited._checkpoint)
raises(EvaluationCancelled, lambda: limited._charge(0))
raises(AttributeError, lambda: setattr(limited, 'cancelled', False))
assert limited.remaining_steps == 4
assert not issubclass(EvaluationBudgetExceeded, ValueError)
assert not issubclass(EvaluationCancelled, ValueError)
"#).unwrap();
            py.run(source.as_c_str(), Some(&globals), Some(&globals)).unwrap();
        });
    }

    #[test]
    fn real_compiled_programs_share_exact_fuel_across_native_calls() {
        Python::initialize();
        Python::attach(|py| {
            let module = module(py);
            let instance = budget(&module, 12);
            let borrowed = instance.extract::<PyRef<'_, PyEvaluationBudget>>().unwrap();
            let square = CompiledExpr::try_from_ops(vec![
                CompiledOp::LoadVar(0), CompiledOp::LoadVar(0), CompiledOp::Mul(2),
            ]).unwrap();
            let shifted = CompiledExpr::try_from_ops(vec![
                CompiledOp::LoadVar(0), CompiledOp::LoadConst(1.0), CompiledOp::Add(2),
            ]).unwrap();
            let first = with_evaluation_meter(py, Some(&borrowed), |meter| {
                square.try_eval_finite_with_meter(&[3.0], meter)
            }).unwrap();
            assert_eq!(first, 9.0);
            assert_eq!(remaining(&instance, "remaining_steps"), 6);
            let second = with_evaluation_meter(py, Some(&borrowed), |meter| {
                shifted.try_eval_finite_with_meter(&[3.0], meter)
            }).unwrap();
            assert_eq!(second, 4.0);
            assert_eq!(remaining(&instance, "remaining_steps"), 0);
            assert_eq!(remaining(&instance, "remaining_allocations"), 100_000 - 2);
            assert_eq!(remaining(&instance, "remaining_memory_bytes"), 256 * 1024 * 1024 - 48);
            let error = with_evaluation_meter(py, Some(&borrowed), |meter| {
                square.try_eval_finite_with_meter(&[4.0], meter)
            }).unwrap_err();
            assert!(error.is_instance_of::<EvaluationBudgetExceeded>(py));
            assert_eq!(remaining(&instance, "remaining_steps"), 0);
            assert_eq!(with_evaluation_meter(py, None, |meter| {
                square.try_eval_finite_with_meter(&[4.0], meter)
            }).unwrap(), 16.0);
        });
    }

    #[test]
    fn real_nested_eval_and_objective_errors_preserve_operational_exception_types() {
        Python::initialize();
        Python::attach(|py| {
            let mut ledger = Budget::new(BudgetLimits::uniform(1, 0));
            let exhausted = ledger.try_charge(Dimension::ComputeSteps, 2).unwrap_err();
            let error = evaluation_error(ObjectiveEvaluationError::Evaluation(
                EvalError::Meter(MeterError::Budget(exhausted)),
            ));
            assert!(error.is_instance_of::<EvaluationBudgetExceeded>(py));
            assert!(error.is_instance_of::<PyRuntimeError>(py));
            assert!(!error.is_instance_of::<PyValueError>(py));
            let cancelled = evaluation_error(ObjectiveEvaluationError::Evaluation(
                EvalError::Meter(MeterError::Cancelled),
            ));
            assert!(cancelled.is_instance_of::<EvaluationCancelled>(py));
            assert!(!cancelled.is_instance_of::<PyValueError>(py));
            let domain = evaluation_error(ObjectiveEvaluationError::Evaluation(EvalError::NonFiniteValue));
            assert!(domain.is_instance_of::<PyValueError>(py));
            assert!(!domain.is_instance_of::<EvaluationBudgetExceeded>(py));
        });
    }

    #[test]
    fn actual_finite_domain_refusal_retains_consumption_and_allows_reuse() {
        Python::initialize();
        Python::attach(|py| {
            let module = module(py);
            let instance = budget(&module, 100);
            let borrowed = instance.extract::<PyRef<'_, PyEvaluationBudget>>().unwrap();
            let log = CompiledExpr::try_from_ops(vec![CompiledOp::LoadVar(0), CompiledOp::Ln]).unwrap();
            let error = with_evaluation_meter(py, Some(&borrowed), |meter| {
                log.try_eval_finite_with_meter(&[-1.0], meter)
            }).unwrap_err();
            assert!(error.is_instance_of::<PyValueError>(py));
            assert_eq!(remaining(&instance, "remaining_steps"), 97);
            assert_eq!(remaining(&instance, "remaining_allocations"), 99_999);
            assert_eq!(with_evaluation_meter(py, Some(&borrowed), |meter| {
                log.try_eval_finite_with_meter(&[1.0], meter)
            }).unwrap(), 0.0);
            assert_eq!(remaining(&instance, "remaining_steps"), 94);
            instance.call_method0("cancel").unwrap();
            let cancelled = with_evaluation_meter(py, Some(&borrowed), |meter| {
                log.try_eval_finite_with_meter(&[1.0], meter)
            }).unwrap_err();
            assert!(cancelled.is_instance_of::<EvaluationCancelled>(py));
            assert_eq!(remaining(&instance, "remaining_steps"), 94);
        });
    }
}
